from pydantic import BaseModel, Field

class DocumentMatch(BaseModel):
    """Represents a single document and its association with legal causes of action."""
    title: str | None = Field(
        description="The title of the document (e.g., '《判决文书 1》')"
    )
    matched_causes: list[str] | None = Field(
        description="The causes of action from the provided task list that match this document"
    )

class Parse(BaseModel):
    """Aggregates document matches for downstream sorting and answer generation."""
    documents: list[DocumentMatch]
